 * @param fieldSources     每个业务字段（location/reading/note）的来源记录键，必须恰好覆盖一次
 * @param operator         执行归并的审核人标识
 */
public record ClusterMergeRequest(
        @NotBlank @Size(max = 128) String requestId,
