                snapshot.version(), snapshot.deleted(), snapshot.siteKey(), snapshot.observationType(),
                Timestamp.from(snapshot.observedAt()), snapshot.deviceId(),
                snapshot.status().name(), snapshot.origin().name(), snapshot.mergedInto(),
