        preview(List.of("obs-3", "obs-1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.members[0].recordKey").value("obs-1"));
        preview(List.of("obs-1", "obs-x")).andExpect(status().isNotFound());
